-- ============================================================
-- ASCT-2026-0403 평가위원 평가의견 시드 (테스트용)
--   - 위원 5명 × 6개 점검항목 (001~006) = 30 row
--   - 점수 4~5점 섞음 / 의견은 간단 문구
--   - 협의회 상태는 007(IN_PROGRESS)로 복원
-- ============================================================

-- 상태 복원 (직전 시도에서 009로 변경됐던 것 되돌림)
UPDATE TPRMPP_BASCTM
   SET ASCT_STS_C = '007',
       LST_CHG_DTM = SYSDATE,
       LST_CHG_USID = 'SYSTEM'
 WHERE ASCT_ID = 'ASCT-2026-0403';

-- 평가의견 30 row (PK: ASCT_ID+ENO+CKG_ITM_C 복합)





COMMIT;

PROMPT === 시드 결과: 항목별 평균 ===
SELECT CKG_ITM_C, ROUND(AVG(CKG_RCRD), 2) AS AVG_SCORE, COUNT(*) AS CNT
FROM TPRMPP_BEVALM
WHERE ASCT_ID='ASCT-2026-0403' AND DEL_YN='N'
GROUP BY CKG_ITM_C
ORDER BY CKG_ITM_C;

PROMPT === 협의회 상태 ===
SELECT ASCT_ID, ASCT_STS_C FROM TPRMPP_BASCTM WHERE ASCT_ID='ASCT-2026-0403';

EXIT;
